1: #!/usr/bin/env node
2: 
3: // ───────────────────────────────────────────────────────────────────
4: // MODULE: Divergent Pivot Transaction
5: // ───────────────────────────────────────────────────────────────────
6: //
7: // One pivot transaction split across process boundaries. prepare persists
8: // everything up through "which seats are still missing" and returns;
9: // record-seat durably records one externally-obtained seat result per native
10: // dispatch step; finalize re-derives all context from disk and completes the
11: // transaction. A workflow interpreter cannot hand the library an in-process
12: // dispatchSeat callback. Only the running agent can natively dispatch a
13: // Council seat, so these three subcommands are the workflow-facing seam.
14: //
15: // Only prepare is mode-owned: it derives its input from the research or the
16: // review state and renders that mode's seat prompts. record-seat and finalize
17: // act on the persisted transaction alone, so neither takes a loop type.
18: 
19: 'use strict';
20: 
21: // ───────────────────────────────────────────────────────────────────
22: // 1. IMPORTS
23: // ───────────────────────────────────────────────────────────────────
24: 
25: const fs = require('node:fs');
26: const path = require('node:path');
27: 
28: require('tsx/cjs');
29: 
30: const {
31:   preparePivotTransaction,
32:   recordPivotSeatResult,
33:   finalizePivotTransaction,
34: } = require('../lib/deep-loop/divergent-pivot.ts');
35: 
36: // ───────────────────────────────────────────────────────────────────
37: // 2. CONSTANTS
38: // ───────────────────────────────────────────────────────────────────
39: 
40: const EXIT_USAGE = 64;
41: 
42: const USAGE = [
43:   'Usage: divergent-pivot.cjs prepare|record-seat|finalize',
44:   '[prepare: --loop-type research|review --artifact-root <dir> --config <path>',
45:   '--state-log <path> --strategy <path> --registry <path>',
46:   '--current-iteration <n> --max-iterations <n> --trigger-reason <reason>]',
47:   '[record-seat: JSON envelope on stdin]',
48:   '[finalize: --paths-json <json> --pivot-id <id> --resumed true|false]',
49: ].join(' ');
50: 
51: const FLAG_KEYS = Object.freeze({
52:   '--loop-type': 'loopType',
53:   '--artifact-root': 'artifactRoot',
54:   '--config': 'config',
55:   '--state-log': 'stateLog',
56:   '--strategy': 'strategy',
57:   '--registry': 'registry',
58:   '--current-iteration': 'currentIteration',
59:   '--max-iterations': 'maxIterations',
60:   '--trigger-reason': 'triggerReason',
61:   '--paths-json': 'pathsJson',
62:   '--pivot-id': 'pivotId',
63:   '--resumed': 'resumed',
64: });
65: 
66: const FLAGS_BY_KEY = Object.freeze(
67:   Object.fromEntries(Object.entries(FLAG_KEYS).map(([flag, key]) => [key, flag])),
68: );
69: 
70: // Every flag a subcommand lists is required, and a flag it does not read is
71: // rejected. A silently ignored flag would let the workflow believe it passed a
72: // value that never reached the transaction, and no path flag may fall back to
73: // a default. record-seat reads no flags at all: its whole payload is the stdin
74: // envelope.
75: const SUBCOMMAND_FLAGS = Object.freeze({
76:   prepare: Object.freeze([
77:     'loopType',
78:     'artifactRoot',
79:     'config',
80:     'stateLog',
81:     'strategy',
82:     'registry',
83:     'currentIteration',
84:     'maxIterations',
85:     'triggerReason',
86:   ]),
87:   'record-seat': Object.freeze([]),
88:   finalize: Object.freeze(['pathsJson', 'pivotId', 'resumed']),
89: });
90: 
91: // The two mode libraries export the same shape under mode-owned names. Keeping
92: // the module path and both function names in one table means prepare has a
93: // single code path and a new mode is one entry, not a third branch.
94: const MODE_ADAPTERS = Object.freeze({
95:   research: Object.freeze({
