329: /**
330:  * Spawns a CJS script as a child process with configurable timeout and returns stdout/stderr.
331:  */
332: export function spawnCjs(
333:   scriptPath: string,
334:   args: string[] = [],
335:   options: SpawnCjsOptions = {},
336: ): Promise<SpawnCjsResult> {
337:   return new Promise((resolvePromise) => {
338:     const child = spawn(process.execPath, [scriptPath, ...args], {
339:       cwd: options.cwd ?? runtimeRoot,
340:       env: options.env ?? process.env,
341:       stdio: [options.stdin === undefined ? 'ignore' : 'pipe', 'pipe', 'pipe'],
342:       detached: process.platform !== 'win32',
343:     });
344:     let stdout = '';
345:     let stderr = '';
346:     let timedOut = false;
347:     let forceKillTimer: NodeJS.Timeout | null = null;
348:     const killProcessTree = (signal: NodeJS.Signals): void => {
349:       if (process.platform !== 'win32' && child.pid !== undefined) {
350:         try {
351:           process.kill(-child.pid, signal);
352:           return;
353:         } catch {
354:           // The process may have exited between the timeout and escalation.
355:         }
356:       }
357:       child.kill(signal);
358:     };
359:     const timeout = options.timeoutMs
360:       ? setTimeout(() => {
361:           timedOut = true;
362:           killProcessTree('SIGTERM');
363:           forceKillTimer = setTimeout(() => {
364:             killProcessTree('SIGKILL');
365:           }, FORCE_KILL_DELAY_MS);
366:         }, options.timeoutMs)
367:       : null;
368: 
369:     child.stdout?.setEncoding('utf8');
370:     child.stderr?.setEncoding('utf8');
371:     if (options.stdin !== undefined) {
372:       child.stdin?.end(options.stdin);
373:     }
374:     child.stdout?.on('data', (chunk) => { stdout += chunk; });
375:     child.stderr?.on('data', (chunk) => { stderr += chunk; });
376:     child.on('close', (exitCode, signal) => {
377:       if (timeout) clearTimeout(timeout);
378:       if (forceKillTimer) clearTimeout(forceKillTimer);
379:       resolvePromise({
380:         exitCode,
381:         stdout: stdout.trim(),
382:         stderr: stderr.trim(),
383:         signal,
384:         timedOut,
385:       });
386:     });
387:   });
388: }
