158:   for (const field of ['text', 'focus', 'title', 'question', 'direction', 'pattern', 'message']) {
159:     const text = normalizeText(value[field]);
160:     if (text) return text;
161:   }
162:   return '';
163: }
164: 
165: function readStringList(value: unknown): string[] {
166:   return Array.isArray(value) ? value.map(readText).filter(Boolean) : [];
167: }
168: 
169: function readPivotEvents(artifactRoot: string): JsonRecord[] {
170:   const pivotsRoot = join(artifactRoot, 'divergent', 'pivots');
171:   if (!existsSync(pivotsRoot)) return [];
172:   return readdirSync(pivotsRoot, { withFileTypes: true })
173:     .filter((entry) => entry.isDirectory())
174:     .sort((left, right) => left.name.localeCompare(right.name))
175:     .flatMap((entry) => readJsonl(join(pivotsRoot, entry.name, 'council', 'state.jsonl')));
176: }
