178: function uniqueCandidates(candidates: readonly PivotCandidate[]): PivotCandidate[] {
179:   const seen = new Set<string>();
180:   return candidates.filter((candidate) => {
181:     const key = `${candidate.id}|${normalizedKey(candidate.fingerprint)}`;
182:     if (seen.has(key)) return false;
183:     seen.add(key);
184:     return true;
185:   });
186: }
