188: function conflictsWithNonGoal(seed: CandidateSeed, nonGoals: readonly string[]): boolean {
189:   const material = ` ${normalizedKey(`${seed.title} ${seed.focus}`)} `;
190:   return nonGoals.some((nonGoal) => {
191:     const excluded = ` ${normalizedKey(nonGoal)} `;
192:     return excluded.trim() !== '' && (material.includes(excluded) || excluded.includes(material));
193:   });
194: }
