200: function buildCandidateSeeds(
201:   registry: JsonRecord,
202:   stateRecords: readonly JsonRecord[],
203: ): CandidateSeed[] {
204:   const seeds: CandidateSeed[] = [];
205:   const add = (seed: CandidateSeed): void => {
206:     if (normalizeText(seed.focus) && normalizeText(seed.evidenceRef)) seeds.push(seed);
207:   };
208: 
209:   for (const [index, question] of [
210:     ...(Array.isArray(registry.openQuestions) ? registry.openQuestions : []),
211:     ...(Array.isArray(registry.carriedForwardOpenQuestions) ? registry.carriedForwardOpenQuestions : []),
212:   ].entries()) {
213:     const text = readText(question);
214:     if (!text) continue;
215:     add({
216:       source: 'adjacent-question',
217:       title: `Investigate adjacent question: ${text}`,
218:       focus: text,
219:       evidenceRef: `findings-registry.json#open-question-${index + 1}`,
220:       relevanceRationale: 'The canonical research registry still carries this question inside the current topic.',
221:     });
222:   }
223: 
224:   const questionConflicts = Array.isArray(registry.questionConflicts) ? registry.questionConflicts : [];
225:   questionConflicts.forEach((conflict, index) => {
226:     if (!isRecord(conflict)) return;
227:     const inboxValue = normalizeText(conflict.inboxValue);
228:     const registryValue = normalizeText(conflict.registryValue);
229:     if (!inboxValue || !registryValue) return;
230:     add({
231:       source: 'contradiction-gap',
232:       title: `Resolve conflicting research question ${index + 1}`,
233:       focus: `Verify whether "${inboxValue}" or "${registryValue}" is supported by the current evidence.`,
234:       evidenceRef: `findings-registry.json#question-conflict-${index + 1}`,
235:       relevanceRationale: 'The reducer recorded an unresolved contradiction in canonical question state.',
236:     });
237:   });
238: 
239:   stateRecords.forEach((record, recordIndex) => {
240:     const evidenceRef = `deep-research-state.jsonl#record-${recordIndex + 1}`;
241:     for (const [field, source, titlePrefix, rationale] of [
242:       ['verificationGaps', 'verification-gap', 'Verify recorded gap', 'The iteration history explicitly records an unresolved verification gap.'],
243:       ['contradictions', 'contradiction-gap', 'Resolve recorded contradiction', 'The iteration history explicitly records contradictory evidence.'],
244:       ['missingSourceClasses', 'missing-source-class', 'Add missing source class', 'The iteration history explicitly identifies an unrepresented source class.'],
245:       ['alternateEvidenceMethods', 'alternate-evidence', 'Apply alternate evidence method', 'The iteration history explicitly identifies an unused evidence method.'],
246:       ['unansweredAdjacentQuestions', 'adjacent-question', 'Investigate adjacent question', 'The iteration history explicitly carries an unanswered adjacent question.'],
247:     ] as const) {
248:       readStringList(record[field]).forEach((text) => add({
249:         source,
250:         title: `${titlePrefix}: ${text}`,
251:         focus: text,
252:         evidenceRef,
253:         relevanceRationale: rationale,
254:       }));
255:     }
256: 
257:     if (Array.isArray(record.graphEvents)) {
258:       record.graphEvents.forEach((event, eventIndex) => {
259:         if (!isRecord(event) || normalizeText(event.relation).toUpperCase() !== 'CONTRADICTS') return;
260:         const sourceId = normalizeText(event.source);
261:         const targetId = normalizeText(event.target);
262:         if (!sourceId || !targetId) return;
263:         add({
264:           source: 'contradiction-gap',
265:           title: `Verify contradiction ${sourceId} -> ${targetId}`,
266:           focus: `Resolve the recorded contradiction between ${sourceId} and ${targetId} using independent evidence.`,
267:           evidenceRef: `${evidenceRef}:graph-event-${eventIndex + 1}`,
268:           relevanceRationale: 'The current coverage graph records this contradiction inside the active research topic.',
269:         });
270:       });
271:     }
272:   });
273: 
274:   const findings = Array.isArray(registry.keyFindings) ? registry.keyFindings : [];
275:   findings.slice(-3).forEach((finding, index) => {
276:     const text = readText(finding);
277:     if (!text) return;
278:     add({
279:       source: 'alternate-evidence',
280:       title: `Independently verify finding: ${text}`,
281:       focus: `Cross-check the finding "${text}" with an evidence method not used by its recorded support.`,
282:       evidenceRef: `findings-registry.json#key-finding-${Math.max(1, findings.length - 2 + index)}`,
283:       relevanceRationale: 'The direction tests an existing in-scope finding rather than widening the research topic.',
284:     });
285:   });
286: 
287:   return seeds;
288: }
