290: // ───────────────────────────────────────────────────────────────────
291: // 4. SEAT PROMPTS
292: // ───────────────────────────────────────────────────────────────────
293: 
294: /** Render the exact parseable result contract for one native research Council seat. */
295: export function renderResearchPivotSeatPrompt(
296:   seat: PivotSeatMandate,
297:   dispatchContext: {
298:     readonly candidates: readonly PivotCandidate[];
299:     readonly previousFocus: string;
300:     readonly normalizedTrigger: string;
301:   },
302: ): string {
303:   return [
304:     'You are one native research direction-selection Council seat. Do not dispatch sub-agents, write files, or widen the research charter.',
305:     '',
306:     `Seat id: ${seat.id}`,
307:     `Mandate: ${seat.mandate}`,
308:     `Saturation trigger: ${dispatchContext.normalizedTrigger}`,
309:     `Previous focus: ${dispatchContext.previousFocus}`,
310:     '',
311:     'Candidate frontier:',
312:     JSON.stringify(dispatchContext.candidates, null, 2),
313:     '',
314:     'Return exactly one parseable JSON object and no surrounding prose or markdown:',
315:     '{"seatId":"' + seat.id + '","selectedCandidateId":null,"materialEndorsement":false,"rationale":"<non-empty rationale>","blockers":[]}',
316:     'Replace selectedCandidateId with one candidate id string and set materialEndorsement to true only for a material endorsement. Blockers may contain {severity, message, candidateId?}.',
317:   ].join('\n');
318: }
