321: // 5. ADAPTER INPUT
322: // ───────────────────────────────────────────────────────────────────
323: 
324: /** Derive bounded candidates, prior directions, usage, identity, and mandates from research state. */
325: export function buildResearchPivotPreparationInput(
326:   options: BuildResearchPivotInputOptions,
327: ): ResearchPivotPreparationInput {
328:   if (!Number.isInteger(options.currentIteration) || options.currentIteration < 0) {
329:     throw new TypeError('currentIteration must be a non-negative integer.');
330:   }
331:   if (!Number.isInteger(options.maxIterations) || options.maxIterations < 1) {
332:     throw new TypeError('maxIterations must be a positive integer.');
333:   }
334:   const config = readJson(options.configPath);
335:   const legacyRegistryPath = join(dirname(options.registryPath), 'deep-research-findings-registry.json');
336:   const registry = readJson(existsSync(options.registryPath) ? options.registryPath : legacyRegistryPath);
337:   const strategy = readFileSync(options.strategyPath, 'utf8');
338:   const stateRecords = readJsonl(options.stateLogPath);
339:   const pivotEvents = readPivotEvents(options.artifactRoot);
340:   const lineage = isRecord(config.lineage) ? config.lineage : {};
341:   const sessionId = normalizeText(lineage.sessionId);
342:   const generation = typeof lineage.generation === 'number' || typeof lineage.generation === 'string'
343:     ? lineage.generation
344:     : 1;
345:   if (!sessionId) throw new TypeError('Research config lineage.sessionId is required for a pivot.');
346: 
347:   const latestIteration = stateRecords.filter((record) => record.type === 'iteration').at(-1);
348:   const strategyFocus = extractSection(strategy, '11. NEXT FOCUS');
349:   const previousFocus = normalizeText(strategyFocus) || normalizeText(latestIteration?.focus);
350:   if (!previousFocus) throw new TypeError('A current research focus is required for a pivot.');
351: 
352:   const topic = normalizeText(config.topic);
353:   if (!topic) throw new TypeError('Research config topic is required for boundary validation.');
354:   const nonGoals = extractListText(extractSection(strategy, '4. NON-GOALS'));
355:   const seeds = buildCandidateSeeds(registry, stateRecords);
356:   const boundaryRejections = seeds.filter((seed) => conflictsWithNonGoal(seed, nonGoals));
357:   const acceptedSeeds = seeds.filter((seed) => !conflictsWithNonGoal(seed, nonGoals));
358:   const boundaryRationale = nonGoals.length > 0
359:     ? `Derived from canonical state for topic "${topic}" and checked against ${nonGoals.length} explicit non-goal(s).`
360:     : `Derived from canonical state for topic "${topic}"; no populated non-goal excluded this direction.`;
361:   const candidates = uniqueCandidates(acceptedSeeds.map((seed) => candidateFromSeed(seed, boundaryRationale)));
362: 
363:   const completedEvents = pivotEvents.filter((event) => event.event === 'pivot_completed');
364:   const selectedEvents = pivotEvents.filter((event) => event.event === 'pivot_selected');
365:   const rejectedEvents = pivotEvents.filter((event) => event.event === 'pivot_candidate_rejected');
366:   const saturatedDirections = [...new Set([
367:     ...completedEvents.flatMap((event) => readStringList(event.saturatedDirections)),
368:     ...completedEvents.map((event) => normalizeText(event.previousFocus)).filter(Boolean),
369:     previousFocus,
370:   ])];
371: 
372:   const priorCandidates: PivotCandidate[] = [];
373:   const addPriorText = (value: unknown, source: string, evidenceRef: string): void => {
374:     const candidate = priorCandidate(readText(value), source, evidenceRef);
375:     if (candidate) priorCandidates.push(candidate);
376:   };
377:   addPriorText(previousFocus, 'current-focus', 'deep-research-strategy.md#next-focus');
378:   saturatedDirections.forEach((direction, index) => addPriorText(
379:     direction,
380:     'saturated-direction',
381:     `divergent/pivots#saturated-${index + 1}`,
382:   ));
383:   (Array.isArray(registry.ruledOutDirections) ? registry.ruledOutDirections : []).forEach((entry, index) => addPriorText(
384:     entry,
385:     'ruled-out-direction',
386:     `findings-registry.json#ruled-out-${index + 1}`,
387:   ));
388:   (Array.isArray(registry.rejectedPatterns) ? registry.rejectedPatterns : []).forEach((entry, index) => addPriorText(
389:     entry,
390:     'rejected-pattern',
391:     `findings-registry.json#rejected-pattern-${index + 1}`,
392:   ));
393:   selectedEvents.forEach((event, index) => {
394:     if (isRecord(event.selectedCandidate)) {
395:       priorCandidates.push(event.selectedCandidate as unknown as PivotCandidate);
396:     } else {
397:       addPriorText(event.selectedCandidate, 'selected-direction', `divergent/pivots#selected-${index + 1}`);
398:     }
399:   });
400:   rejectedEvents.forEach((event, index) => addPriorText(
401:     event.candidate,
402:     'adapter-rejected-direction',
403:     `divergent/pivots#candidate-rejected-${index + 1}`,
404:   ));
405: 
406:   const seats: readonly PivotSeatMandate[] = [
407:     {
408:       id: 'seat-001',
409:       mandate: 'Analytical: select the direction that closes the most consequential unanswered evidence gap while remaining inside the research charter.',
410:     },
411:     {
412:       id: 'seat-002',
413:       mandate: 'Critical: challenge candidate relevance, boundary safety, contradiction handling, and risk of re-entering saturated directions.',
414:     },
415:     {
416:       id: 'seat-003',
417:       mandate: 'Pragmatic: select the most evidence-efficient next direction that can produce material information within the remaining iterations.',
418:     },
419:   ];
420:   const identity: PivotIdentityInput = {
421:     sessionId,
422:     generation,
423:     loopType: 'research',
424:     sourceIteration: options.currentIteration,
425:     normalizedTrigger: `research saturation: ${options.triggerReason}`,
426:     ordinal: completedEvents.length + 1,
427:   };
428:   const currentPivotId = derivePivotId(identity);
429:   const currentAttempt = pivotEvents.some((event) => event.pivotId === currentPivotId && event.event === 'pivot_attempt_failed') ? 2 : 1;
430:   const usage: PivotUsage = {
431:     completedPivots: completedEvents.length,
432:     // Seat outputs are capped per council attempt, so only the pivot about to be prepared counts.
433:     councilSeatOutputs: pivotEvents.filter((event) => event.event === 'pivot_seat_returned'
434:       && event.pivotId === currentPivotId
435:       && (event.attempt ?? 1) === currentAttempt).length,
436:     remainingIterations: Math.max(0, options.maxIterations - options.currentIteration),
437:   };
438: 
439:   return {
440:     artifactRoot: options.artifactRoot,
441:     identity,
442:     config: config as unknown as PivotConfigInput,
443:     usage,
444:     seats,
445:     candidates,
446:     priorCandidates: uniqueCandidates(priorCandidates),
447:     previousFocus,
448:     saturatedDirections,
449:     boundaryRejections,
450:   };
451: }

