39:   write(data: unknown): void;
40:   flushNow(): Promise<void>;
41:   close(): Promise<void>;
42: }
43: 
44: const DEFAULT_DEFERRED_WRITE_DEBOUNCE_MS = 50;
45: const DIFF_FIELD_PATTERN = /^[A-Za-z_][A-Za-z0-9_]*$/u;
46: 
47: // ───────────────────────────────────────────────────────────────────
48: // 2. HELPERS
49: // ───────────────────────────────────────────────────────────────────
50: 
51: const serializedStateCache = new Map<string, string>();
52: const serializedJsonlAppendCache = new Map<string, string>();
53: 
54: function canonicalizeJson(value: unknown, isRoot = false): unknown {
55:   if (Array.isArray(value)) {
56:     return value.map((entry) => canonicalizeJson(entry));
57:   }
58: 
59:   if (typeof value !== 'object' || value === null) {
60:     return value;
61:   }
62: 
63:   const source = value as Record<string, unknown>;
64:   const sorted: Record<string, unknown> = {};
65: 
66:   for (const key of Object.keys(source).sort()) {
67:     if (isRoot && key === '_integrity') {
68:       continue;
69:     }
70: 
71:     sorted[key] = canonicalizeJson(source[key]);
72:   }
73: 
74:   return sorted;
75: }
76: 
77: function isJsonRecord(value: unknown): value is Record<string, unknown> {
78:   return typeof value === 'object' && value !== null && !Array.isArray(value);
79: }
80: 
81: function fsyncPath(path: string): void {
82:   let fd: number | undefined;
83:   try {
84:     fd = openSync(path, 'r');
85:     fsyncSync(fd);
86:   } finally {
87:     if (typeof fd === 'number') {
88:       closeSync(fd);
89:     }
90:   }
91: }
92: 
93: function makeTempPath(targetPath: string): string {
94:   return `${targetPath}.tmp.${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2)}`;
95: }
96: 
97: function serializeState(data: unknown): string {
98:   const serialized = JSON.stringify(data);
99:   if (typeof serialized !== 'string') {
100:     throw new TypeError('State data must serialize to JSON.');
101:   }
102:   return serialized;
103: }
104: 
105: function serializePrettyState(data: unknown): string {
106:   const serialized = JSON.stringify(data, null, 2);
107:   if (typeof serialized !== 'string') {
108:     throw new TypeError('State data must serialize to JSON.');
109:   }
110:   return `${serialized}\n`;
111: }
112: 
113: function appendTextWithFsync(path: string, content: string): void {
114:   let fd: number | undefined;
115: 
116:   mkdirSync(dirname(path), { recursive: true });
117:   try {
118:     fd = openSync(path, 'a');
119:     writeFileSync(fd, content, 'utf8');
120:     fsyncSync(fd);
121:   } finally {
122:     if (typeof fd === 'number') {
123:       closeSync(fd);
124:     }
125:   }
126: 
127:   try {
128:     fsyncPath(dirname(path));
129:   } catch {
130:   }
131: }
