133: // ───────────────────────────────────────────────────────────────────
134: // 2a. APPEND LOCK — serializes the diff-gated read-modify-append section so
135: //     two writers can never both decide "not a duplicate" for the same row.
136: // ───────────────────────────────────────────────────────────────────
137: 
138: interface AppendLockOwnerToken {
139:   readonly pid: number;
140:   readonly nonce: string;
141:   readonly acquiredAtIso: string;
142: }
143: 
144: const APPEND_LOCK_DEADLINE_MS = 5_000;
145: const appendLockWait = new Int32Array(new SharedArrayBuffer(4));
146: 
147: function errorCode(error: unknown): string | undefined {
148:   return error && typeof error === 'object' && 'code' in error
149:     ? (error as NodeJS.ErrnoException).code
150:     : undefined;
151: }
152: 
153: function makeAppendLockToken(): AppendLockOwnerToken {
154:   return { pid: process.pid, nonce: randomUUID(), acquiredAtIso: new Date().toISOString() };
155: }
156: 
157: function readAppendLockOwner(lockPath: string): AppendLockOwnerToken | null {
158:   try {
159:     const parsed = JSON.parse(readFileSync(lockPath, 'utf8')) as unknown;
160:     if (
161:       isJsonRecord(parsed)
162:       && Number.isInteger(parsed.pid)
163:       && typeof parsed.nonce === 'string'
164:       && parsed.nonce.length > 0
165:       && typeof parsed.acquiredAtIso === 'string'
166:     ) {
167:       return { pid: parsed.pid as number, nonce: parsed.nonce, acquiredAtIso: parsed.acquiredAtIso };
168:     }
169:     return null;
170:   } catch {
171:     return null;
172:   }
173: }
174: 
175: /** Owner-less (unreadable/corrupt) or dead-pid locks are the only ones eligible for reclaim. */
176: function isAppendLockReclaimable(owner: AppendLockOwnerToken | null): boolean {
177:   return owner === null || !processAlive(owner.pid);
178: }
179: 
180: function writeAppendLockExclusive(lockPath: string, token: AppendLockOwnerToken): boolean {
181:   let fd: number | undefined;
182:   try {
183:     fd = openSync(lockPath, 'wx');
184:     writeFileSync(fd, `${JSON.stringify(token)}\n`, 'utf8');
185:     fsyncSync(fd);
186:   } catch (error: unknown) {
187:     if (errorCode(error) === 'EEXIST') return false;
188:     throw error;
189:   } finally {
190:     if (typeof fd === 'number') closeSync(fd);
191:   }
192:   return true;
193: }
194: 
195: function makeAppendLockClaimPath(lockPath: string, purpose: string): string {
196:   return `${lockPath}.${purpose}.${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2)}`;
197: }
198: 
199: /**
200:  * Atomically claim a dead-owner lock so exactly one reclaimer replaces it.
201:  *
202:  * rename() of a single inode succeeds for only the first caller; every other
203:  * concurrent reclaimer finds the source already gone and loses the race, so
204:  * two reclaimers can never both end up holding the lock.
205:  */
206: function tryReclaimDeadAppendLock(lockPath: string, token: AppendLockOwnerToken): boolean {
207:   const reclaimPath = makeAppendLockClaimPath(lockPath, 'reclaiming');
208:   try {
209:     renameSync(lockPath, reclaimPath);
210:   } catch (error: unknown) {
211:     if (errorCode(error) === 'ENOENT') return false;
212:     throw error;
213:   }
214:   try {
215:     return writeAppendLockExclusive(lockPath, token);
216:   } finally {
217:     rmSync(reclaimPath, { force: true });
218:   }
219: }
220: 
221: function acquireAppendLock(targetPath: string): AppendLockOwnerToken {
222:   const lockPath = `${targetPath}.lock`;
223:   mkdirSync(dirname(targetPath), { recursive: true });
224:   const token = makeAppendLockToken();
225:   const deadline = Date.now() + APPEND_LOCK_DEADLINE_MS;
226:   while (true) {
227:     if (writeAppendLockExclusive(lockPath, token)) return token;
228:     if (isAppendLockReclaimable(readAppendLockOwner(lockPath)) && tryReclaimDeadAppendLock(lockPath, token)) {
229:       return token;
230:     }
231:     if (Date.now() >= deadline) {
232:       throw new Error(`Timed out acquiring append lock: ${lockPath}`);
233:     }
234:     Atomics.wait(appendLockWait, 0, 0, 2);
235:   }
236: }
237: 
238: /** Compare-and-delete release: only the exact owner tuple that acquired the lock may drop it. */
239: function releaseAppendLock(targetPath: string, token: AppendLockOwnerToken): void {
240:   const lockPath = `${targetPath}.lock`;
241:   const claimPath = makeAppendLockClaimPath(lockPath, 'releasing');
242:   try {
243:     renameSync(lockPath, claimPath);
244:   } catch (error: unknown) {
245:     if (errorCode(error) === 'ENOENT') return;
246:     throw error;
247:   }
248: 
249:   const current = readAppendLockOwner(claimPath);
250:   if (current !== null && current.pid === token.pid && current.nonce === token.nonce) {
251:     rmSync(claimPath, { force: true });
252:     try {
253:       fsyncPath(dirname(lockPath));
254:     } catch {
255:     }
256:     return;
257:   }
258: 
259:   // A reclaimer already replaced this lock with its own; restore it untouched
260:   // rather than dropping a successor's live claim (compare-and-swap restore).
261:   if (!existsSync(lockPath)) {
262:     renameSync(claimPath, lockPath);
263:     try {
264:       fsyncPath(dirname(lockPath));
265:     } catch {
266:     }
267:     return;
268:   }
269:   rmSync(claimPath, { force: true });
270: }
271: 
272: function withAppendLock<T>(targetPath: string, operation: () => T): T {
273:   const token = acquireAppendLock(targetPath);
274:   try {
275:     return operation();
276:   } finally {
277:     releaseAppendLock(targetPath, token);
278:   }
279: }
280: 
281: function readLastJsonlLine(path: string): string | null {
282:   if (!existsSync(path)) {
283:     return null;
284:   }
285: 
286:   const lines = readFileSync(path, 'utf8').split(/\r?\n/u);
287:   for (let index = lines.length - 1; index >= 0; index -= 1) {
288:     const line = lines[index].trim();
289:     if (line !== '') {
290:       return line;
291:     }
292:   }
293:   return null;
294: }
295: 
296: function readLastDiffFingerprint(path: string, diffField: string | undefined): string | null {
297:   const line = readLastJsonlLine(path);
298:   if (line === null) {
299:     return null;
300:   }
301: 
302:   if (diffField === undefined) {
303:     return line;
304:   }
305: 
306:   try {
307:     const parsed = JSON.parse(line) as unknown;
308:     if (isJsonRecord(parsed) && typeof parsed[diffField] === 'string') {
309:       return parsed[diffField];
310:     }
311:   } catch {
312:   }
313: 
314:   return null;
315: }
316: 
317: function computeSerializedHash(serialized: string): string {
318:   const digest = createHash('sha256').update(serialized).digest('hex');
319:   return `sha256:${digest}`;
320: }
321: 
322: function attachDiffField(data: unknown, diffField: string | undefined, fingerprint: string): unknown {
323:   if (diffField === undefined) {
324:     return data;
325:   }
326: 
327:   if (!DIFF_FIELD_PATTERN.test(diffField)) {
328:     throw new TypeError('Diff field must be a valid JSON object key.');
329:   }
330: 
331:   if (!isJsonRecord(data)) {
332:     throw new TypeError('Diff field requires JSON object row data.');
333:   }
334: 
335:   return { ...data, [diffField]: fingerprint };
336: }
337: 
338: function serializeIntegrityPayload(data: unknown): string {
339:   const serialized = JSON.stringify(canonicalizeJson(data, true));
340:   if (typeof serialized !== 'string') {
341:     throw new TypeError('State data must serialize to JSON.');
342:   }
343:   return serialized;
344: }
345: 
346: // ───────────────────────────────────────────────────────────────────
347: // 3. EXPORTS
348: // ───────────────────────────────────────────────────────────────────
349: 
350: /**
351:  * Compute a deterministic SHA-256 digest for JSON state.
352:  *
353:  * The root `_integrity` field is excluded so stamped snapshots can verify
354:  * against the same payload that produced their stored hash.
355:  *
356:  * @param obj - JSON-serializable object or registry snapshot.
357:  * @returns Digest formatted as `sha256:<hex>`.
358:  * @throws If the input cannot be serialized as JSON.
359:  */
360: export function computeIntegrityHash(obj: unknown): string {
361:   const digest = createHash('sha256').update(serializeIntegrityPayload(obj)).digest('hex');
362:   return `sha256:${digest}`;
363: }
364: 
365: /**
366:  * Attach an integrity stamp to a JSON object before writing it.
367:  *
368:  * This mutates the provided object so callers can stamp existing state
369:  * snapshots without changing their write path.
370:  *
371:  * @param obj - JSON object to stamp.
372:  * @returns The same object with `_integrity` set.
373:  */
374: export function stampIntegrity<T extends object>(obj: T): T & { _integrity: string } {
375:   const stamped = obj as T & { _integrity: string };
376:   stamped._integrity = computeIntegrityHash(obj);
377:   return stamped;
378: }
379: 
380: /**
381:  * Verify a stamped JSON object and warn rather than throw on mismatch.
382:  *
383:  * This helper is for whole-object registry/config snapshots only. Append-only
384:  * JSONL needs a deferred sidecar or per-record design, so this function does
385:  * not stamp or validate JSONL streams. A mismatch is warning-only for now;
386:  * blocking mutation is a follow-up once operators have confirmed warnings
387:  * surface reliably in practice.
388:  *
389:  * @param obj - Stamped JSON object to verify.
390:  * @returns True when the stored integrity hash matches; false otherwise.
391:  */
392: export function verifyIntegrity(obj: unknown): boolean {
393:   if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) {
394:     console.warn('[deep-loop] State integrity check skipped: expected stamped object state.');
395:     return false;
396:   }
397: 
398:   const storedIntegrity = (obj as Record<string, unknown>)._integrity;
399:   const computedIntegrity = computeIntegrityHash(obj);
400: 
401:   if (storedIntegrity === computedIntegrity) {
402:     return true;
403:   }
404: 
405:   console.warn('[deep-loop] State integrity mismatch detected; continuing with on-disk state.', {
406:     stored: typeof storedIntegrity === 'string' ? storedIntegrity : null,
407:     computed: computedIntegrity,
408:   });
409:   return false;
410: }
411: 
412: /**
413:  * Atomically write JSON-serializable state to a file.
414:  *
415:  * Writes to a temp file first, fsyncs it, then renames onto the target
416:  * so readers always see either the previous complete file or the new one.
417:  * Prefer writeStateIfChangedAtomic for production snapshot writes so
418:  * unchanged state does not pay the fsync + rename cost.
419:  *
420:  * @param path - Target file path.
421:  * @param data - Serializable data to write.
422:  * @throws If write, fsync, or rename fails.
423:  */
424: export function writeStateAtomic(path: string, data: unknown): void {
425:   writeTextAtomic(path, serializePrettyState(data));
426: }
427: 
428: /**
429:  * Atomically write JSON-serializable state only when its serialized form changed.
430:  *
431:  * The cache is keyed by the resolved target path so equivalent relative paths
432:  * share the same skip decision.
433:  *
434:  * @param path - Target file path.
435:  * @param data - Serializable data to write.
436:  * @param cache - Optional cache override for isolated callers or tests.
437:  * @returns True when a write occurred; false when unchanged state was skipped.
438:  * @throws If serialization, write, fsync, or rename fails.
439:  */
440: export function writeStateIfChangedAtomic(
441:   path: string,
442:   data: unknown,
443:   cache: Map<string, string> = serializedStateCache,
444: ): boolean {
445:   const targetPath = resolve(path);
446:   const serialized = serializeState(data);
447: 
448:   if (cache.get(targetPath) === serialized) {
449:     return false;
450:   }
451: 
452:   writeStateAtomic(targetPath, data);
453:   cache.set(targetPath, serialized);
454:   return true;
455: }
456: 
457: /**
458:  * Append a JSONL row only when a stable serialized diff has changed.
459:  *
460:  * The optional diff field persists the fingerprint on the row so short-lived
461:  * command processes can compare against the last ledger write without sharing
462:  * in-memory cache state.
463:  *
464:  * @param path - Target JSONL path.
465:  * @param data - Serializable row data to append.
466:  * @param options - Optional cache, diff payload, and persisted diff field.
467:  * @returns True when a row was appended; false when unchanged state was skipped.
468:  * @throws If serialization, read, append, or fsync fails.
469:  */
470: export function appendJsonlIfChangedAtomic(
471:   path: string,
472:   data: unknown,
473:   options: AppendJsonlIfChangedAtomicOptions = {},
474: ): boolean {
475:   const targetPath = resolve(path);
476:   const cache = options.cache ?? serializedJsonlAppendCache;
477:   const cacheKey = `${targetPath}\0${options.diffField ?? ''}`;
478:   const diffSerialized = serializeState(options.diffData ?? data);
479:   const diffFingerprint = options.diffField === undefined
480:     ? diffSerialized
481:     : computeSerializedHash(diffSerialized);
482: 
483:   return withAppendLock(targetPath, () => {
484:     if (cache.get(cacheKey) === diffFingerprint) {
485:       return false;
486:     }
487: 
488:     if (readLastDiffFingerprint(targetPath, options.diffField) === diffFingerprint) {
489:       cache.set(cacheKey, diffFingerprint);
490:       return false;
491:     }
492: 
493:     const row = attachDiffField(data, options.diffField, diffFingerprint);
494:     const serializedRow = serializeState(row);
495:     const currentContent = existsSync(targetPath) ? readFileSync(targetPath, 'utf8') : '';
496:     const separator = currentContent === '' || currentContent.endsWith('\n') ? '' : '\n';
497: 
498:     appendTextWithFsync(targetPath, `${separator}${serializedRow}\n`);
499:     cache.set(cacheKey, diffFingerprint);
500:     return true;
501:   });
502: }
