504: /**
505:  * Create a debounced atomic writer for replace-style JSON snapshots.
506:  *
507:  * The default debounce window is 50 ms. Writes during that window supersede
508:  * older pending state, so callers must use `flushNow()` or `close()` from
509:  * process-exit handlers to avoid losing the final in-memory version on crash.
510:  * Append-only JSONL streams should keep immediate append semantics instead of
511:  * using this coalescing path.
512:  *
513:  * @param path - Target file path.
514:  * @param options - Optional debounce configuration.
515:  * @returns Deferred writer bound to the resolved target path.
516:  */
517: export function createDeferredAtomicWriter(
518:   path: string,
519:   options: DeferredAtomicWriterOptions = {},
520: ): DeferredAtomicWriter {
521:   const targetPath = resolve(path);
522:   const debounceMs = Math.max(0, options.debounceMs ?? DEFAULT_DEFERRED_WRITE_DEBOUNCE_MS);
523:   let pendingContent: string | null = null;
524:   let pendingVersion = 0;
525:   let flushTimer: ReturnType<typeof setTimeout> | null = null;
526:   let flushPromise: Promise<void> | null = null;
527:   let hasLastFlushError = false;
528:   let lastFlushError: unknown = null;
529:   let isClosed = false;
530: 
531:   function clearFlushTimer(): void {
532:     if (flushTimer !== null) {
533:       clearTimeout(flushTimer);
534:       flushTimer = null;
535:     }
536:   }
537: 
538:   function scheduleFlush(): void {
539:     if (flushTimer !== null || flushPromise !== null || isClosed) {
540:       return;
541:     }
542: 
543:     flushTimer = setTimeout(() => {
544:       flushTimer = null;
545:       void drainPendingWrites().catch((error: unknown) => {
546:         hasLastFlushError = true;
547:         lastFlushError = error;
548:         console.error('[deep-loop] Deferred atomic writer flush failed.', error);
549:       });
550:     }, debounceMs);
551:   }
552: 
553:   async function drainPendingWrites(): Promise<void> {
554:     if (flushPromise !== null) {
555:       await flushPromise;
556:       if (pendingContent !== null) {
557:         await drainPendingWrites();
558:       }
559:       return;
560:     }
561: 
562:     if (pendingContent === null) {
563:       return;
564:     }
565: 
566:     const activeFlush = (async (): Promise<void> => {
567:       while (pendingContent !== null) {
568:         const content = pendingContent;
569:         const capturedVersion = pendingVersion;
570: 
571:         // Give same-turn callers a chance to mark the writer dirty again.
572:         await Promise.resolve();
573: 
574:         writeTextAtomic(targetPath, content);
575: 
576:         if (pendingVersion === capturedVersion) {
577:           pendingContent = null;
578:         }
579:       }
580:     })();
581: 
582:     flushPromise = activeFlush;
583:     try {
584:       await activeFlush;
585:     } finally {
586:       if (flushPromise === activeFlush) {
587:         flushPromise = null;
588:       }
589:     }
590:   }
591: 
592:   async function flushNow(): Promise<void> {
593:     clearFlushTimer();
594:     if (hasLastFlushError) {
595:       hasLastFlushError = false;
596:       const error = lastFlushError;
597:       lastFlushError = null;
598:       throw error;
599:     }
600:     await drainPendingWrites();
601:   }
602: 
603:   return {
604:     write(data: unknown): void {
605:       if (isClosed) {
606:         throw new Error('Deferred atomic writer is closed.');
607:       }
608: 
609:       pendingContent = serializePrettyState(data);
610:       pendingVersion += 1;
611:       scheduleFlush();
612:     },
613: 
614:     flushNow,
615: 
616:     async close(): Promise<void> {
617:       isClosed = true;
618:       await flushNow();
619:     },
620:   };
621: }
