const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const ROOT = '/Users/michelkerkmeester/worktrees/public/464-ed-012-pivot-hygiene/.skilled/skills/system-deep-loop';
const CLI = path.join(ROOT, 'runtime', 'scripts', 'divergent-pivot.cjs');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'dlr-repro-'));
const config = path.join(root, 'deep-research-config.json');
const registry = path.join(root, 'deep-research-findings-registry.json');
const strategy = path.join(root, 'deep-research-strategy.md');
const stateLog = path.join(root, 'deep-research-state.jsonl');
fs.writeFileSync(config, JSON.stringify({
  topic: 'Divergent pivot CLI retry contract',
  lineage: { sessionId: 'session-cli-retry', generation: 1 },
}, null, 2) + '\n');
fs.writeFileSync(registry, JSON.stringify({
  keyFindings: ['First in-scope finding', 'Second in-scope finding'],
}, null, 2) + '\n');
fs.writeFileSync(strategy, '# Deep Research Strategy\n\n## 11. NEXT FOCUS\n\nCurrent saturated focus\n\n');
fs.writeFileSync(stateLog, '');

function run(args, input) {
  const r = spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8', input });
  console.log('===', args[0], 'status', r.status);
  console.log('STDOUT:', r.stdout);
  console.log('STDERR:', r.stderr);
  return r;
}

const prepareArgs = [
  'prepare', '--loop-type', 'research', '--artifact-root', root,
  '--config', config, '--state-log', stateLog, '--strategy', strategy,
  '--registry', registry, '--current-iteration', '3', '--max-iterations', '10',
  '--trigger-reason', 'saturated',
];

const first = run(prepareArgs);
const firstJson = JSON.parse(first.stdout);
const selectedCandidateId = firstJson.dispatchContext.candidates[0].id;
for (const seat of firstJson.missingSeats) {
  const rejected = seat.id === 'seat-003';
  run(['record-seat'], JSON.stringify({
    paths: firstJson.paths,
    pivotId: firstJson.pivotId,
    seat,
    status: rejected ? 'rejected' : 'fulfilled',
    output: rejected ? null : {
      seatId: seat.id,
      selectedCandidateId,
      materialEndorsement: true,
      rationale: 'The selected direction is materially supported by the supplied evidence',
      blockers: [],
    },
    error: rejected ? { name: 'Error', message: 'seat unavailable' } : null,
    startedAtIso: '2026-11-17T12:00:00.000Z',
    completedAtIso: '2026-11-17T12:00:01.000Z',
    durationMs: 1000,
  }));
}
run(['finalize', '--paths-json', JSON.stringify(firstJson.paths), '--pivot-id', firstJson.pivotId, '--resumed', 'false']);
run(prepareArgs);

console.log('=== state tail');
console.log(fs.readFileSync(path.join(root, 'divergent', 'pivots', firstJson.pivotId, 'council', 'state.jsonl'), 'utf8').split('\n').slice(-8).join('\n'));

